# part_ui_as.map — cụm ui_as: màn menu trong game (as) + các panel danh sách (bg và lớp con) + dc, cs
# Bằng chứng: restored/raw/as.java, ab.java (xử lý phím của menu), cd.java/ci.java/ae.java (mở menu), Patch.java/SfxUi.java (as.o/as.p).
# Giá trị as.o_B (menuPage): 1 thanh tab, 2 Trạng thái, 3 Sủng vật, 4 Kỹ năng, 5 Trang bị, 6 Túi đồ, 7 Nhiệm vụ, 8 Đồ giám, 9 Hệ thống
#   (= chỉ số tab de.c() + 2, ab.java:41), 12 đổi hình dạng, 13 chọn đối tượng dùng vật phẩm, 14 tiệm kỹ năng, 15 tiệm đồ/trang bị.

# ---- GameMenu (as) ----
C as GameMenu HIGH  # tab 'Trạng thái','Sủng vật'...'Hệ thống' (de), paint dispatch theo as.o_B, cd.a_as
F as.o_B menuPage HIGH  # 1 tab bar, 2..9 = tab index+2 (ab.java:41), 12/13/14/15 trang phụ; Patch/SfxUi 'as.o' group==9 hệ thống
F as.p_B systemPage HIGH  # trang của tab Hệ thống: 0 menu,1 Lưu,2 Tải,3 âm lượng (SfxUi PAGE_VOLUME),4 'Trở về menu chính?',5 xác nhận ghi/tải,6 'Tải điểm QQ'
F as.q_B petPage HIGH  # tab Sủng vật: 0 list,1 menu thao tác,2 Thuộc tính,3 'Chắc chắn thả',4 thông báo,5 Kỹ năng,7 Cấy,8 Tinh luyện (ab.g)
F as.t_B equipPage HIGH  # tab Trang bị: 0 ô trang bị,1 túi trang bị,2 menu Thay/Tháo/Bỏ/Khảm,3 khảm đá quý (ab.f)
F as.w_B questPage HIGH  # tab Nhiệm vụ: 0 chọn chính/phụ tuyến,1 list chính,2 list phụ,3 chi tiết,4 menu Xem/Bỏ,5 'Xóa nhiệm vụ đang chọn?' (ab.e)
F as.z_B dexPage HIGH  # tab Đồ giám: 0 danh sách,1 chi tiết pet,2 hợp thành (ab.d, 'Đang hợp thành')
F as.v_B bagPage HIGH  # tab Túi đồ: 0 chọn loại,1 lưới,2 menu Dùng/Bán/Bỏ,3 bán (số lượng+giá),4 bỏ (số lượng)
F as.x_B skillPage HIGH  # tab Kỹ năng: 0 danh sách,1 mô tả kỹ năng (ab.a_V o_B==4)
F as.s_B petSkillPage MED  # q_B==5: 0 danh sách kỹ năng pet,1 mô tả
F as.A_B skillShopPage HIGH  # o_B 14 'Tiệm kỹ năng': 0 list,1 chọn người học,2 'Xác nhận học kỹ năng'
F as.B_B shopPage HIGH  # o_B 15: 0 list,1 hộp số lượng mua (ab.c)
F as.u_B socketResult MED  # 0 đang chọn đá, 1 hiện 'Chúc mừng‚khảm trang bị thành công'
F as.y_B shopType HIGH  # 0 itemShop,1 equipShop,2 skillShop (as.b(int) /bin/shop.bin)
F as.D_B saveConfirmMode HIGH  # 1 xác nhận ghi đè (Lưu), 2 xác nhận tải; quay lại p_B = D_B
F as.a_B petActionIndex HIGH  # con trỏ menu thao tác pet (e_AString[a_B])
F as.b_B equipSlotIndex HIGH  # 0..5 ô 'Vũ khí','Mũ','Áo','Giày','Dây chuyền','Nhẫn', 6..11 món bộ trang bị
