F as.c_B equipBagScrollRow HIGH  # hàng cuộn lưới trang bị (a_S - c_B*f_S)
F as.d_B equipActionIndex HIGH  # con trỏ d_AString 'Thay','Tháo','Bỏ','Khảm'
F as.e_B bagTabIndex HIGH  # 0 'Vật phẩm',1 'Nguyên liệu',2 'Khác' (j_AString)
F as.f_B bagScrollRow HIGH  # hàng cuộn lưới túi đồ
F as.g_B bagItemIndex HIGH  # ô đang chọn a_AAAS[e_B][g_B]
